    12	async function testFetch(url: string, name: string): Promise<{ success: boolean; status?: number; error?: string }> {
    13	  try {
    14	    const response = await axios.get(url, {
    15	      timeout: 15000,
    16	      headers: { 'User-Agent': 'EventPulse/1.0 Test' },
    17	    });
    18	    return { success: response.status === 200, status: response.status };
    19	  } catch (err: any) {
    20	    return { success: false, error: err.message };
    21	  }
    22	}
