    24	async function testJsonLd(url: string, name: string): Promise<{ found: number; events: string[] }> {
    25	  try {
    26	    const response = await axios.get(url, {
    27	      timeout: 15000,
    28	      headers: { 'User-Agent': 'EventPulse/1.0 Test' },
    29	    });
    30	
    31	    if (response.status !== 200) {
    32	      return { found: 0, events: [] };
    33	    }
    34	
    35	    const html = response.data;
    36	    const $ = cheerio.load(html);
    37	    let count = 0;
    38	    const titles: string[] = [];
    39	
    40	    $('script[type="application/ld+json"]').each((_, el) => {
    41	      try {
    42	        const content = $(el).html();
    43	        if (!content) return;
    44	        const data = JSON.parse(content);
    45	
    46	        // Check ItemList
    47	        if (data['@type'] === 'ItemList' && data.itemListElement) {
    48	          for (const item of data.itemListElement) {
    49	            if (item.item?.['@type'] === 'Event' && item.item.name) {
    50	              count++;
    51	              if (titles.length < 3) titles.push(item.item.name);
    52	            }
    53	          }
    54	        }
    55	
    56	        // Check @graph
    57	        if (data['@graph']) {
    58	          for (const item of data['@graph']) {
    59	            if (item['@type'] === 'Event' && item.name) {
    60	              count++;
    61	              if (titles.length < 3) titles.push(item.name);
    62	            }
    63	          }
    64	        }
    65	
    66	        // Check EventSeries
    67	        if (data['@type'] === 'EventSeries' && data.subEvent) {
    68	          for (const sub of data.subEvent) {
    69	            if (sub['@type'] === 'Event' && sub.name) {
    70	              count++;
    71	              if (titles.length < 3) titles.push(sub.name);
    72	            }
    73	          }
    74	        }
    75	
    76	        // Check direct Event
    77	        if (data['@type'] === 'Event' && data.name) {
    78	          count++;
    79	          if (titles.length < 3) titles.push(data.name);
    80	        }
    81	      } catch (e) {
    82	        // Skip
    83	      }
    84	    });
    85	
    86	    return { found: count, events: titles };
    87	  } catch (err: any) {
    88	    return { found: 0, events: [] };
    89	  }
    90	}
