    92	async function testWordPress(url: string, name: string): Promise<{ found: number; events: string[] }> {
    93	  try {
    94	    const response = await axios.get(url, {
    95	      timeout: 15000,
    96	      headers: { 'User-Agent': 'EventPulse/1.0 Test', 'Accept': 'application/json' },
    97	    });
    98	
    99	    if (response.status !== 200 || !Array.isArray(response.data)) {
   100	      return { found: 0, events: [] };
   101	    }
   102	
   103	    const events = response.data.slice(0, 5);
   104	    const titles = events.map((e: any) => e.title?.rendered || e.title || 'untitled');
   105	
   106	    return { found: response.data.length, events: titles };
   107	  } catch (err: any) {
   108	    return { found: 0, events: [] };
   109	  }
   110	}
