   112	async function testElasticsearch(url: string, name: string): Promise<{ found: number; events: string[] }> {
   113	  try {
   114	    const query = {
   115	      size: 20,
   116	      query: {
   117	        bool: {
   118	          must: [{ range: { tixStartDate: { gte: 'now' } } }],
   119	        },
   120	      },
   121	      sort: [{ tixStartDate: { order: 'asc' } }],
   122	    };
   123	
   124	    const response = await axios.post(url, query, {
   125	      timeout: 15000,
   126	      headers: { 'User-Agent': 'EventPulse/1.0 Test', 'Content-Type': 'application/json' },
   127	    });
   128	
   129	    if (response.status !== 200 || !response.data?.hits?.hits) {
   130	      return { found: 0, events: [] };
   131	    }
   132	
   133	    const hits = response.data.hits.hits;
   134	    const titles = hits.slice(0, 3).map((h: any) => h._source?.drupalTitle || h._source?.tixName || 'untitled');
   135	
   136	    return { found: hits.length, events: titles };
   137	  } catch (err: any) {
   138	    return { found: 0, events: [] };
   139	  }
   140	}
