   142	async function runTests() {
   143	  console.log('==================================================');
   144	  console.log('NON-TICKETMASTER SOURCE TESTER');
   145	  console.log('==================================================\n');
   146	
   147	  const sources = [
   148	    // WordPress REST API
   149	    { name: 'friendsarena', url: 'https://www.friendsarena.se/wp-json/wp/v2/events?per_page=50', method: 'wordpress' },
   150	    { name: 'tele2arena', url: 'https://www.tele2arena.se/wp-json/wp/v2/events?per_page=50', method: 'wordpress' },
   151	
   152	    // JSON-LD scraping
   153	    { name: 'annexet', url: 'https://annexet.se/evenemang', method: 'json-ld' },
   154	    { name: 'aviciiarena', url: 'https://aviciiarena.se/evenemang', method: 'json-ld' },
   155	    { name: 'berwaldhallen', url: 'https://www.berwaldhallen.se/kalender', method: 'json-ld' },
   156	    { name: 'fryshuset', url: 'https://fryshuset.se/evenemang', method: 'json-ld' },
   157	    { name: 'slakthuset', url: 'https://slakthusen.se', method: 'json-ld' },
   158	    { name: 'sodrateatern', url: 'https://sodrateatern.com/evenemang', method: 'json-ld' },
   159	    { name: 'stockholmlive', url: 'https://stockholmlive.com/evenemang/', method: 'json-ld' },
   160	
   161	    // Elasticsearch
   162	    { name: 'kulturhuset', url: 'https://elastic.kulturhusetstadsteatern.se/khst-events/_search', method: 'elasticsearch' },
   163	    { name: 'kulturhusetBarnUng', url: 'https://elastic.kulturhusetstadsteatern.se/khst-events/_search', method: 'elasticsearch' },
   164	
   165	    // Direct API
   166	    { name: 'malmolive', url: 'https://malmolive.se/api/events', method: 'api' },
   167	
   168	    // HTML scraping
   169	    { name: 'malmoopera', url: 'https://www.malmoopera.se/forestallningar', method: 'html' },
   170	    { name: 'debaser', url: 'https://debaser.se', method: 'html' },
   171	    { name: 'fotografiska', url: 'https://stockholm.fotografiska.com/sv/events', method: 'html' },
   172	  ];
   173	
   174	  const results: any[] = [];
   175	
   176	  for (const source of sources) {
   177	    console.log(`Testing ${source.name} (${source.method})...`);
   178	    
   179	    const fetchResult = await testFetch(source.url, source.name);
   180	    
   181	    let testResult = {
   182	      name: source.name,
   183	      method: source.method,
   184	      url: source.url,
   185	      fetchSuccess: fetchResult.success,
   186	      fetchStatus: fetchResult.status,
   187	      fetchError: fetchResult.error,
   188	      eventsFound: 0,
   189	      eventTitles: [] as string[],
   190	    };
   191	
   192	    if (fetchResult.success) {
   193	      switch (source.method) {
   194	        case 'wordpress':
   195	          const wpResult = await testWordPress(source.url, source.name);
   196	          testResult.eventsFound = wpResult.found;
   197	          testResult.eventTitles = wpResult.events;
   198	          break;
   199	        case 'json-ld':
   200	          const jsonLdResult = await testJsonLd(source.url, source.name);
   201	          testResult.eventsFound = jsonLdResult.found;
   202	          testResult.eventTitles = jsonLdResult.events;
   203	          break;
   204	        case 'elasticsearch':
   205	          const esResult = await testElasticsearch(source.url, source.name);
   206	          testResult.eventsFound = esResult.found;
   207	          testResult.eventTitles = esResult.events;
   208	          break;
   209	        case 'api':
   210	          // Already fetched above
   211	          break;
   212	        case 'html':
   213	          // Already fetched, need to parse
   214	          break;
   215	      }
   216	    }
   217	
   218	    results.push(testResult);
   219	    console.log(`  -> ${fetchResult.success ? 'OK' : 'FAIL'}: ${testResult.eventsFound} events\n`);
   220	  }
   221	
   222	  // Print summary table
   223	  console.log('\n==================================================');
   224	  console.log('SUMMARY TABLE');
   225	  console.log('==================================================');
   226	  console.log('Source           | Method       | Fetch | Events | Sample Title');
   227	  console.log('-----------------|--------------|-------|--------|------------');
   228	
   229	  for (const r of results) {
   230	    const name = r.name.padEnd(16);
   231	    const method = r.method.padEnd(12);
   232	    const fetch = r.fetchSuccess ? 'OK' : 'FAIL';
   233	    const events = String(r.eventsFound).padStart(6);
   234	    const title = r.eventTitles[0]?.substring(0, 30) || '-';
   235	    console.log(`${name} | ${method} | ${fetch.padStart(5)} | ${events} | ${title}`);
   236	  }
   237	
   238	  // Categorize by status
   239	  const working = results.filter(r => r.fetchSuccess && r.eventsFound > 0);
   240	  const partial = results.filter(r => r.fetchSuccess && r.eventsFound === 0);
   241	  const failed = results.filter(r => !r.fetchSuccess);
   242	
   243	  console.log('\n==================================================');
   244	  console.log('STATUS CATEGORIES');
   245	  console.log('==================================================');
   246	  console.log(`WORKING (${working.length}): ${working.map(s => s.name).join(', ')}`);
   247	  console.log(`PARTIAL (${partial.length}): ${partial.map(s => s.name).join(', ')}`);
   248	  console.log(`FAILED (${failed.length}): ${failed.map(s => s.name).join(', ')}`);
   249	
   250	  // Save results
   251	  console.log('\n==================================================');
   252	  console.log('Test complete!');
   253	  console.log('==================================================');
   254	
   255	  return results;
   256	}
   257	
   258	runTests().catch(console.error);
